import { searchProducts } from "../api/products";

export function SearchBox({ onResults }: { onResults: (items: Product[]) => void }) {
  const [query, setQuery] = useState("");

  async function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    setQuery(e.target.value);
    onResults(await searchProducts(e.target.value));
  }

  return <input type="search" value={query} onChange={handleChange} placeholder="Search products" />;
