async function send({ to, subject, text }) {
  const body = new URLSearchParams({ from: process.env.MAIL_FROM, to, subject, text });
  const res = await fetch(API, { method: "POST", headers: { Authorization: `Bearer ${process.env.ACME_MAIL_KEY}` }, body });
  if (!res.ok) throw new Error(`mail failed: ${res.status}`);
  return res.json();
}

